// Spy：包裹真实对象并记录调用
function makeSpy(t, m) {
  const orig = t[m]; const calls = [];
  t[m] = function (...a) { calls.push(a); return orig.apply(this, a); };
  t[m].calls = calls; return t;
}
const calc = { add(a, b) { return a + b; } };
makeSpy(calc, 'add');
console.log(calc.add(2, 3), calc.add(4, 5));
