async function waitFor(predicate, { timeoutMs = 1000, intervalMs = 50 } = {}) {
  const start = Date.now();
  while (Date.now() - start < timeoutMs) {
    if (predicate()) return true;
    await new Promise((r) => setTimeout(r, intervalMs));
  }
  return false;
}

async function checkLoaded(page) {
  return waitFor(() => page.isVisible('.submit-btn'), { timeoutMs: 5000, intervalMs: 50 });
}

function makeSpy(target, method) {
  const orig = target[method];
  const calls = [];
  target[method] = function (...args) {
    calls.push(args);
    return orig.apply(this, args);
  };
  target[method].calls = calls;
  return target;
}

const calc = { add(a, b) { return a + b; } };
makeSpy(calc, 'add');
console.log(calc.add(2, 3), calc.add(4, 5));
console.log(JSON.stringify(calc.add.calls));

