function runGate(checks) {
  const failed = checks.filter((c) => !c.run()).map((c) => c.name);
  return failed.length === 0 ? 'GREEN' : `RED: ${failed.join(',')}`;
}
const gate = runGate([
  { name: 'lint', run: () => true },
  { name: 'typecheck', run: () => true },
  { name: 'coverage', run: () => 85 >= 80 },
  { name: 'build', run: () => true },
]);
console.log(gate);
const gate2 = runGate([
  { name: 'lint', run: () => false },
  { name: 'typecheck', run: () => true },
  { name: 'coverage', run: () => 70 >= 80 },
  { name: 'build', run: () => true },
]);
console.log(gate2);
