function verifyProvider(contract, handler) {
  return contract.interactions.map((it) => {
    const actual = handler(it.withRequest);
    const ok =
      actual.status === it.willRespondWith.status &&
      actual.body.id === it.willRespondWith.body.id;
    return { path: it.withRequest.path, ok };
  });
}

// Fake 内存版提供者：满足契约
const good = (req) => req.path === '/orders/1'
  ? { status: 200, body: { id: 1, total: 99 } }
  : { status: 404, body: null };

// 被破坏的提供者：把 id 类型改成了字符串
const broken = (req) => req.path === '/orders/1'
  ? { status: 200, body: { id: '1', total: 99 } }
  : { status: 404, body: null };

const contract = { interactions: [
  { withRequest: { path: '/orders/1' }, willRespondWith: { status: 200, body: { id: 1 } } },
] };
console.log(JSON.stringify(verifyProvider(contract, good)));
console.log(JSON.stringify(verifyProvider(contract, broken)));
